<script setup lang="ts">
import {appendHours,inspectTimeSeries} from './timeSeries';
import SeriesPreview from './SeriesPreview.vue';
import NetworkView from './NetworkView.vue';
import NetworkEditor from './NetworkEditor.vue';
import AlashankouImport from './AlashankouImport.vue';
import {ref,computed,onMounted,watch} from 'vue';
const csv=defineModel<string>({required:true});const props=defineProps<{section?:string;parameters:Record<string,number>;placement:{wind_node:number;pv_node:number};disabled:boolean}>();
const network=defineModel<any>('network',{required:true});const failures=defineModel<number[]>('failures',{required:true});const emit=defineEmits<{source:[csv:string,source:any]}>();
const tab=ref('源荷时序');const message=ref('');const page=ref(0);
const pending=ref<{name:string;csv:string}|null>(null);const preview=computed(()=>pending.value?inspectTimeSeries(pending.value.csv):null);const previewRows=computed(()=>pending.value?.csv.trim().split(/\r?\n/).slice(1).filter(line=>line.trim()).slice(0,5).map(line=>line.split(','))||[]);let uploadRequest=0;
watch(csv,()=>{pending.value=null;++uploadRequest});
function applyImport(){if(!pending.value||preview.value?.totalIssues)return;csv.value=pending.value.csv;pending.value=null;page.value=0;message.value='已应用导入数据，请保存工程；原计算档案保持不变。'}
const startTime=ref('2026-01-01T00:00');const additionalHours=ref(24);
function append(){try{const next=appendHours(csv.value,startTime.value,additionalHours.value);csv.value=next;page.value=Math.floor((next.trim().split(/\r?\n/).length-2)/24);message.value='已新增'+additionalHours.value+'小时，新增功率初值均为0，请录入实际数据后保存工程。'}catch(e){message.value=e instanceof Error?e.message:String(e)}}
const rows=computed(()=>csv.value.trim().split(/\r?\n/).slice(1).filter(line=>line.trim()).map(line=>line.split(',')));
watch(()=>rows.value.length,()=>{page.value=Math.max(0,Math.min(page.value,Math.max(0,Math.ceil(rows.value.length/24)-1)))});
const inspection=computed(()=>inspectTimeSeries(csv.value));
const shown=computed(()=>rows.value.slice(page.value*24,page.value*24+24));
const titles:Record<string,string>={node:'节点编号',type:'节点类型',pd_kw:'有功负荷 / kW',qd_kvar:'无功负荷 / kvar',vm_init_pu:'初始电压 / pu',line:'线路编号',from_node:'首节点',to_node:'末节点',r_ohm:'电阻 / Ω',x_ohm:'电抗 / Ω',status:'投运状态'};
const fields=['timestamp','load_kw','wind_kw','pv_kw'];
function edit(row:number,col:number,event:Event){const all=rows.value.map(r=>[...r]);all[row][col]=(event.target as HTMLInputElement).value;csv.value=fields.join(',')+'\n'+all.map(r=>r.join(',')).join('\n')+'\n'}
async function upload(e:Event){const input=e.target as HTMLInputElement;const request=++uploadRequest;pending.value=null;try{const f=input.files?.[0];if(!f)return;if(f.size>2000000)throw Error('CSV文件不得超过2MB');const text=(await f.text()).replace(/^\uFEFF/,'');if(request!==uploadRequest)return;pending.value={name:f.name,csv:text};message.value='已读取文件，请查看预览后应用。'}catch(e){if(request===uploadRequest)message.value=e instanceof Error?e.message:String(e)}finally{input.value=''}}

function download(){const u=URL.createObjectURL(new Blob(['\uFEFF'+csv.value],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='source-load.csv';a.click();URL.revokeObjectURL(u)}
const parameterNames:Record<string,string>={storage_power_kw:'储能功率 / kW',storage_energy_kwh:'储能容量 / kWh',emergency_gen_kw:'应急电源功率 / kW',grid_channel_kw:'上级电网容量 / kW',soc_initial_ratio:'初始SOC / 比例',soc_min_ratio:'SOC下限 / 比例',soc_max_ratio:'SOC上限 / 比例',eta_charge:'充电效率 / 比例',eta_discharge:'放电效率 / 比例',critical_load_ratio:'关键负荷占比',important_load_ratio:'重要负荷占比'};

watch(()=>props.section,value=>{if(value)tab.value=value},{immediate:true});
</script>
<template><p v-if="message" class="notice">{{message}}</p><AlashankouImport v-if="tab==='阿拉山口资料'" :disabled="disabled" @apply="(csv,source)=>emit('source',csv,source)"/><NetworkEditor v-else-if="['电网拓扑','电网节点','电网线路'].includes(tab)" v-model="network" v-model:failures="failures" :disabled="disabled" :placement="placement" :focus="tab"/><article v-else-if="tab==='源荷时序'"><div class="actions"><label class="button">导入CSV<input type="file" accept=".csv" @change="upload" :disabled="disabled" hidden></label><button @click="download">导出当前数据</button></div><div v-if="pending&&preview" class="validation import-preview" :class="{invalid:preview.totalIssues}"><h3>CSV导入预览 · {{pending.name}}</h3><p>待导入{{preview.count}}条，当前工作区{{rows.length}}条。应用后替换当前源荷输入。</p><p v-if="!preview.totalIssues">本地格式校验通过，前5行预览如下。</p><ul v-else><li v-for="(issue,i) in preview.issues" :key="i">{{issue.row?'第'+issue.row+'行':'数据范围'}}：{{issue.message}}</li></ul><p v-if="preview.totalIssues>20">共{{preview.totalIssues}}项问题，仅展示前20项。</p><div class="scroll"><table><tr><th>时间</th><th>负荷 / kW</th><th>风电 / kW</th><th>光伏 / kW</th></tr><tr v-for="(row,i) in previewRows" :key="i"><td v-for="(cell,j) in row" :key="j">{{cell}}</td></tr></table></div><div class="actions"><button @click="applyImport" :disabled="disabled||!!preview.totalIssues">应用导入数据</button><button @click="pending=null">取消导入</button></div><p v-if="preview.totalIssues">请修正文件后重新选择；当前工作区尚未替换。</p></div><details class="sequence-entry"><summary>建立或追加逐时时序</summary><p>已有数据时从末条时间的下一小时追加；新增负荷、风电、光伏初值均为0，请按实际数据编辑。</p><div class="actions"><label v-if="!rows.length">起始时间<input type="datetime-local" v-model="startTime" :disabled="disabled" step="3600"></label><label>新增小时数<input type="number" min="1" max="8760" v-model.number="additionalHours" :disabled="disabled"></label><button @click="append" :disabled="disabled">新增空白时段</button></div></details><p>共 {{rows.length}} 条，功率单位kW。此表与平衡模块共享同一数据；支持逐格编辑，计算前后端校验连续小时与非负功率。</p><div class="validation" :class="{invalid:inspection.totalIssues}"><strong>{{inspection.totalIssues?'数据校验发现 '+inspection.totalIssues+' 项问题':'本地格式校验通过'}}</strong><p>本地检查用于录入辅助，提交时仍由计算服务复核。错误行号包含CSV表头。</p><ul v-if="inspection.totalIssues"><li v-for="(issue,i) in inspection.issues" :key="i"><button v-if="issue.row>1" @click="page=Math.floor(csv.trim().split(/\r?\n/).slice(1,issue.row-1).filter(line=>line.trim()).length/24)">第{{issue.row}}行</button><span v-else>{{issue.row===1?'表头':'数据范围'}}</span>：{{issue.message}}</li></ul><p v-if="inspection.totalIssues>20">仅展示前20项，请修正后继续检查。</p></div><SeriesPreview :csv="csv"/><details><summary>展开逐小时数据编辑表</summary><div class="scroll data-table"><table><thead><tr><th>时间</th><th>负荷 / kW</th><th>风电 / kW</th><th>光伏 / kW</th></tr></thead><tbody><tr v-for="(r,i) in shown"><td v-for="(v,j) in r"><input :value="v" :type="j?'number':'text'" :disabled="disabled" @input="edit(page*24+i,j,$event)"></td></tr></tbody></table></div><div class="actions"><button @click="page--" :disabled="page===0">上一页</button><span>第{{page+1}} / {{Math.max(1,Math.ceil(rows.length/24))}}页</span><button @click="page++" :disabled="(page+1)*24>=rows.length">下一页</button></div></details></article><article v-else-if="tab==='电网拓扑'"><NetworkView v-if="network" :network="network" :placement="placement"/></article><article v-else-if="tab==='源储参数'"><h3>统一资源参数</h3><p>此处修改直接用于平衡计算。IEEE33模型中储能和应急电源接入根节点。</p><label v-for="(value,key) in parameters" class="field">{{parameterNames[key]||key}}<input type="number" :value="value" :disabled="disabled" step="any" @input="parameters[key]=Number(($event.target as HTMLInputElement).value)"></label></article><article v-else><p>{{network?.source}}。当前计算采用固定拓扑，只读展示；支路容量在平衡模块单独配置。</p><div class="scroll data-table" v-if="network"><table><tr><th v-for="key in Object.keys((tab==='电网节点'?network.nodes:network.lines)[0])">{{titles[key]||key}}</th></tr><tr v-for="r in tab==='电网节点'?network.nodes:network.lines"><td v-for="v in r">{{v}}</td></tr></table></div></article></template>
<style scoped>.validation{margin-top:16px;padding:14px;background:#eef8f4;border-left:3px solid #16856b}.validation.invalid{background:#fff7ed;border-color:#c17a20}.validation p{font-size:12px}.validation li{margin:6px 0}.validation li button{padding:3px 8px}.sequence-entry{margin-top:16px;padding:12px;background:#f3f8f8}.sequence-entry summary{cursor:pointer}.sequence-entry label{display:flex;gap:10px;align-items:center}.sequence-entry input[type=datetime-local]{width:220px}.module-tabs{display:flex;gap:8px;overflow:auto;margin:20px 0}.current{background:#087b7b;color:white}.data-table{max-height:560px;margin:18px 0}input{border:1px solid #cbdde0;padding:8px;width:120px}td:first-child input{width:190px}.actions{align-items:center}th{position:sticky;top:0}</style>
